    const t = openTrace(out, 'r1')
    t.toolContent('../../escape', 'x')
    const files = allFiles(out)
    expect(files).toHaveLength(1)
    expect(files[0].startsWith(join(t.dir, 'tools'))).toBe(true)
  })

  it('writes container output to containers/<n>.txt', () => {
    const t = openTrace(out, 'r1')
    t.containerOutput(1, 'hallo wereld')
    t.containerOutput(2, 'tweede')
    expect(readFileSync(join(t.dir, 'containers', '1.txt'), 'utf8')).toBe('hallo wereld')
    expect(readFileSync(join(t.dir, 'containers', '2.txt'), 'utf8')).toBe('tweede')
  })

  it('writes the container event with n and outputBytes', () => {
    const t = openTrace(out, 'r1')
    t.containerOutput(3, 'abc')
    t.event({ type: 'container', n: 3, kind: 'verify', source: 'gate', exitCode: 0, timedOut: false, durationMs: 5, outputBytes: Buffer.byteLength('abc') })
    const line = readTrace(t.dir).find((e) => e.type === 'container')
    expect(line).toMatchObject({ type: 'container', n: 3, kind: 'verify', source: 'gate', exitCode: 0, timedOut: false, durationMs: 5, outputBytes: 3 })
  })
})

function readTrace(dir: string): Array<Record<string, unknown> & { type: string }> {
  return readFileSync(join(dir, 'trace.jsonl'), 'utf8').trim().split('\n').map((l) => JSON.parse(l))
}"}

